        const halfVisibleW = cw / (2 * targetZoom);
        const halfVisibleH = ch / (2 * targetZoom);
        const minX = halfVisibleW;
        const maxX = cw - halfVisibleW;
        const minY = halfVisibleH;
        const maxY = ch - halfVisibleH;
        
